class ParticleSystem{constructor(){this.items=[]}burst(x,y,n=12,type="spark"){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=30+Math.random()*130;this.items.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.5+Math.random()*.5,max:.9,size:2+Math.random()*5,type})}}update(dt){for(const p of this.items){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=90*dt;p.life-=dt}this.items=this.items.filter(p=>p.life>0).slice(-450)}draw(c){for(const p of this.items){c.globalAlpha=Math.max(0,p.life/p.max);c.fillStyle=p.type==="coin"?"#ffd43b":p.type==="hit"?"#ff5d7a":"#fff";c.beginPath();c.arc(p.x,p.y,p.size*(.5+p.life/p.max),0,Math.PI*2);c.fill()}c.globalAlpha=1}}
let particles=new ParticleSystem();
let audioCtx=null;
function beep(freq=500,dur=.07,type="sine"){if(!gameState.settings.sound)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.045,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(e){}}
function showToast(msg){const el=document.getElementById("toast");if(!el)return;el.textContent=msg;el.classList.add("show");clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove("show"),1800)}